for f in sorted(cache_dir.rglob('*')):
    if f.is_file():
        data = f.read_bytes()
        gz_pos = data.find(b'\x1f\x8b\x08')
        if gz_pos >= 0:
            try:
                decoded = zlib.decompress(data[gz_pos + 10:], -15)
